#!/usr/bin/env node
// Regenerates lib/course-asset-sizes.ts from what is actually in public/.
//
// WHY A GENERATED FILE AND NOT A HEAD REQUEST: the download button has to state a size BEFORE the
// farmer commits their data to it, and asking the network for 60 content-lengths first would spend
// a chunk of the very thing being budgeted — on the connection least able to afford it. So the
// sizes ship with the app.
//
// A generated file drifts the moment someone re-encodes an asset, which is why
// tests/offline-pack.test.ts re-runs this logic against disk and fails on any mismatch. Run:
//   node scripts/gen-asset-sizes.mjs

import { readdirSync, statSync, writeFileSync, existsSync } from 'node:fs';
import { join, relative } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(fileURLToPath(new URL('.', import.meta.url)), '..');
const PUBLIC = join(ROOT, 'public');

// Only the course payload. Render assets and app icons are not part of what a learner downloads.
const ROOTS = ['course-decks', 'course-audio', 'course-animations', 'course-images'];

export function collectSizes() {
  const sizes = {};
  for (const top of ROOTS) {
    const dir = join(PUBLIC, top);
    if (!existsSync(dir)) continue;
    walk(dir, sizes);
  }
  return Object.fromEntries(Object.entries(sizes).sort(([a], [b]) => (a < b ? -1 : 1)));
}

function walk(dir, out) {
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    if (entry.name.startsWith('.')) continue;
    const full = join(dir, entry.name);
    if (entry.isDirectory()) walk(full, out);
    else out[`/${relative(PUBLIC, full)}`] = statSync(full).size;
  }
}

function render(sizes) {
  const rows = Object.entries(sizes).map(([url, bytes]) => `  '${url}': ${bytes},`).join('\n');
  const total = Object.values(sizes).reduce((a, b) => a + b, 0);
  return `// GENERATED by scripts/gen-asset-sizes.mjs — do not edit by hand.
//
// Every course asset in public/, with its exact size. The offline download states a total before
// it starts, and tests/offline-pack.test.ts fails if any entry here disagrees with disk.
//
// ${Object.keys(sizes).length} files, ${(total / 1048576).toFixed(1)} MB total.

export const COURSE_ASSET_SIZES: Readonly<Record<string, number>> = Object.freeze({
${rows}
});
`;
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const sizes = collectSizes();
  const out = join(ROOT, 'lib', 'course-asset-sizes.ts');
  writeFileSync(out, render(sizes));
  const total = Object.values(sizes).reduce((a, b) => a + b, 0);
  console.log(`wrote ${Object.keys(sizes).length} entries (${(total / 1048576).toFixed(1)} MB) -> ${relative(ROOT, out)}`);
}
